        } else {
            throw new IOException("Invalid message format: packed field detected but not enabled");
        }
    }
}

private void readPackedLengthDelimitedField() throws IOException {
    // Read the length of the packed field from the input stream
    int length = input.readRawVarint32();

    // Update the length-delimited state to reflect the current packed field
    if (length > packedFieldBytesLimit) {
        throw new IOException("Packed field length exceeds the limit");
    }
    remainingPackedFieldBytes = length;
    currentPackedFieldValue = input.readBytes();
}

public int readTag() throws IOException {
    int tag = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            return tag;
        }
        tag <<= 7;
        tag += b & 0x7F;
        if ((b & 0x80) == 0) {
            return tag;
        }
    }
}

